(126, 15, 6, 119, 'UTS', '2026-10-12 09:45:46', '2026-10-12 10:24:35', '2026-10-12 10:25:51', 31, 4, NULL, '62', '62', NULL, '192.168.40.90', 0, 'a:35:{i:279;s:1:\"D\";i:280;s:1:\"C\";i:281;s:1:\"C\";i:282;s:1:\"C\";i:283;s:1:\"C\";i:284;s:1:\"C\";i:285;s:1:\"C\";i:286;s:1:\"D\";i:287;s:1:\"C\";i:288;s:1:\"C\";i:289;s:1:\"D\";i:290;s:1:\"B\";i:291;s:1:\"C\";i:292;s:1:\"C\";i:293;s:1:\"A\";i:294;s:1:\"B\";i:295;s:1:\"A\";i:296;s:1:\"B\";i:297;s:1:\"C\";i:298;s:1:\"B\";i:299;s:1:\"A\";i:300;s:1:\"C\";i:301;s:1:\"A\";i:302;s:1:\"B\";i:303;s:1:\"B\";i:304;s:1:\"B\";i:305;s:1:\"C\";i:306;s:1:\"B\";i:307;s:1:\"C\";i:308;s:1:\"C\";i:309;s:1:\"C\";i:310;s:1:\"B\";i:311;s:1:\"A\";i:312;s:1:\"C\";i:313;s:1:\"C\";}', 'a:5:{i:314;s:142:\"1 perdamaian abadi2 mengantarkan rakyat indonesia kedepan pintu kemerdekaan perdamaian abadi dan keadilan soasial b agi seluruh rakyat indosia\";i:315;s:112:\"keimanan dengan tuhan harus di iringi dengan kasih sayang sesama orang lain tanpa membedakan status atau derajat\";i:316;s:154:\"1 adil dalam mengambil keputusan2 tidak membedakan status orang lain2 sopan dalam berperilaku baik di lingkungan masyarakat sekolah keluarga maupun sosial\";i:317;s:172:\"makna sila keadilan atau sila ke 5 yaitu setiap warga negara akan mendapatkan perilaku adil dan mendapatkan hak dan kewajiban sesuai hukum yang tercatat di negara indonesia\";i:318;s:395:\"cara agar seorang pelajar bisa menjiwai pancasilabelajar tentang isi dari pancasila agar bisa menajalankan sesuai dengan yang tertulis di sila pansila1 menghargai pebedaan dimanapun kita berada contohnya menghargai teman yang berbeda agama2 menjalakan kewajiban disekola contohnya piket kelas3 melakukan musywarah ketika akan mengambil keputusan contoh kegiatan calon pemilihan ketos dan waketos\";}', NULL, 0, NULL, NULL, NULL, 0),
(127, 15, 6, 136, 'UTS', '2026-10-12 09:46:41', '2026-10-12 10:25:11', '2026-10-12 10:27:05', 19, 16, NULL, '38', '38', NULL, '192.168.40.80', 0, 'a:35:{i:279;s:1:\"D\";i:280;s:1:\"C\";i:281;s:1:\"A\";i:282;s:1:\"C\";i:283;s:1:\"C\";i:284;s:1:\"B\";i:285;s:1:\"B\";i:286;s:1:\"C\";i:287;s:1:\"C\";i:288;s:1:\"C\";i:289;s:1:\"C\";i:290;s:1:\"A\";i:291;s:1:\"C\";i:292;s:1:\"C\";i:293;s:1:\"D\";i:294;s:1:\"B\";i:295;s:1:\"E\";i:296;s:1:\"D\";i:297;s:1:\"A\";i:298;s:1:\"B\";i:299;s:1:\"A\";i:300;s:1:\"C\";i:301;s:1:\"A\";i:302;s:1:\"A\";i:303;s:1:\"B\";i:304;s:1:\"B\";i:305;s:1:\"D\";i:306;s:1:\"B\";i:307;s:1:\"E\";i:308;s:1:\"A\";i:309;s:1:\"A\";i:310;s:1:\"C\";i:311;s:1:\"A\";i:312;s:1:\"A\";i:313;s:1:\"A\";}', 'a:5:{i:314;s:221:\"melindugi segenap bangasa indonesia dan seluruh tumpah darah indonesia memajukan kejestraan umum mecerdaskan kehidupan bangsa ikut melaksanakan ketertiban dunia berdasarkan kemerdekan  perdamaian abadi dan keadilan sosial\";i:315;s:149:\"sila kegunaan ( sila1 ) harus menjadi fandasi memperkuat persaudaraan dan tolenransi bukan memecah belah demi menjaga kesatuan bansa ( sila 1 dan 3) \";i:316;s:88:\"1 berani membela yang benar 2 membantu teman yang kesusahan 3 tidak bersifat semena mena\";i:317;s:153:\"berari setiap warga negara berhakj mendapatkan perlakuan yang adil  mendapatkan kesepakatan yang sama serta memperoleh hak dan kewajiban secara seimbang \";i:318;s:152:\"beribadah sesuai agama dan kepercayaan nya masing masing menjaga kesatuan dan tidak melakukan perundunggan bermusawarah saat mengambil keputusan bersama\";}', NULL, 0, NULL, NULL, NULL, 0);
