(132, 15, 6, 137, 'UTS', '2026-10-12 09:48:40', '2026-10-12 10:30:03', '2026-10-12 10:30:09', 32, 3, NULL, '64', '64', NULL, '192.168.40.45', 0, 'a:35:{i:279;s:1:\"D\";i:280;s:1:\"C\";i:281;s:1:\"C\";i:282;s:1:\"C\";i:283;s:1:\"C\";i:284;s:1:\"C\";i:285;s:1:\"C\";i:286;s:1:\"D\";i:287;s:1:\"C\";i:288;s:1:\"C\";i:289;s:1:\"D\";i:290;s:1:\"B\";i:291;s:1:\"C\";i:292;s:1:\"C\";i:293;s:1:\"D\";i:294;s:1:\"B\";i:295;s:1:\"C\";i:296;s:1:\"B\";i:297;s:1:\"C\";i:298;s:1:\"B\";i:299;s:1:\"A\";i:300;s:1:\"C\";i:301;s:1:\"A\";i:302;s:1:\"B\";i:303;s:1:\"B\";i:304;s:1:\"B\";i:305;s:1:\"C\";i:306;s:1:\"B\";i:307;s:1:\"C\";i:308;s:1:\"C\";i:309;s:1:\"C\";i:310;s:1:\"B\";i:311;s:1:\"A\";i:312;s:1:\"C\";i:313;s:1:\"C\";}', 'a:5:{i:314;s:225:\"-melindungi segenap bangsa indonesia dan seluruh tumpah darah indonsia-memajukan kesejahteraan umum-mencerdaskan kehidupan bangsa-ikut melaksanakan ketertiban dunia berdasarkan kemerdekaan perdamaian abadi dan keadilan sosial\";i:315;s:145:\"sila kegunaan (sila 1) harus menjadi fondasi yang memperkuat persaudaraan dan toleransi bukan memecah belah demi menjaga kesatuan bangsa (sila 3)\";i:316;s:196:\"1 menghormati hak asasi sesama manusia tanpa membeda-bedakan2 gemar melakukan aksi kemanusiaan (donasi bencana menjenguk orang sakit)3 menggembangkan sikap tenggang rasa4 berani membela kebenaran \";i:317;s:156:\"maknanya adalah keseimbangan antara hak dan kewajiban secara adil di bdang hukum politik ekonomi dan sosial serta bergotong royong untuk kemakmuran bersama \";i:318;s:128:\"belajar dengan tekun dan jujur menghargai perbedaan pendapat serta diskusi kelompok dan berteman tanpa memandang suku atau agama\";}', NULL, 0, NULL, NULL, NULL, 0),
