(699, 26, 16, 10, 'UTS', '2026-10-13 08:01:05', '2026-10-13 08:43:04', '2026-10-13 08:43:12', 28, 7, NULL, '56', '56', NULL, '192.168.40.38', 0, 'a:35:{i:694;s:1:\"B\";i:695;s:1:\"D\";i:696;s:1:\"E\";i:697;s:1:\"B\";i:698;s:1:\"A\";i:699;s:1:\"D\";i:700;s:1:\"B\";i:701;s:1:\"E\";i:702;s:1:\"C\";i:703;s:1:\"E\";i:704;s:1:\"B\";i:705;s:1:\"C\";i:706;s:1:\"B\";i:707;s:1:\"D\";i:708;s:1:\"D\";i:709;s:1:\"B\";i:710;s:1:\"E\";i:711;s:1:\"B\";i:712;s:1:\"C\";i:713;s:1:\"D\";i:714;s:1:\"C\";i:715;s:1:\"E\";i:716;s:1:\"E\";i:717;s:1:\"B\";i:718;s:1:\"A\";i:719;s:1:\"D\";i:720;s:1:\"E\";i:721;s:1:\"C\";i:722;s:1:\"E\";i:723;s:1:\"B\";i:724;s:1:\"D\";i:725;s:1:\"A\";i:726;s:1:\"B\";i:727;s:1:\"A\";i:728;s:1:\"C\";}', 'a:5:{i:729;s:191:\"pajak adalah kontribusi wajib yang  kepada negara yang terutang oleh orang pribadi atau badan yang bersifat memaksa berdasarkan undang undang  dengan tidak mendapatkan imbalan secara langsung\";i:730;s:377:\"pajak adalah kontribusi wajib yang  kepada negara yang terutang oleh orang pribadi atau badan yang bersifat memaksa dan tidak mendapat imbalan secara langsung sedangkan retribusi adalah iuran yang dikenakan atau dibebankan kepada rakyat atas pemanfaatan atau penggunaan fasilitas umum kepada rakyat untuk memakmurkan kesejahtraan rakyat dan mendapatkan imbalan secara langsung \";i:731;s:199:\"utang pajak timbul apabila sudah adanya peraturan yang berdasarkan dan telat terpenuhinya atau terjadi suatu sasaran pemajakan yang terdiri dari keadaan keadaan  tertentu atau juga peristiwa tertentu\";i:732;s:79:\"- Office Assesment System- Self Assesment System- With Holding Assesment System\";i:733;s:198:\"hak wajib pajak juga berhak mengajukan permohonan atau penundaan atas penyampaian SPT tahunan pajak penghasilan PPh  orang pribadi maupun pajak penghasilan badan sesuai dengan kententuan yang sesuai\";}', NULL, 0, NULL, NULL, NULL, 0),
