INSERT INTO `soal` (`id_soal`, `id_mapel`, `nomor`, `soal`, `jenis`, `pilA`, `pilB`, `pilC`, `pilD`, `pilE`, `jawaban`, `file`, `file1`, `fileA`, `fileB`, `fileC`, `fileD`, `fileE`) VALUES
(119, 2, 1, ' Ayat tentang perintah <i>fastabiqul khairat</i> terdapat dalam &hellip;', 1, ' QS. Al-Baqarah: 183', ' QS. Al-Baqarah: 148', ' QS. Al-Maidah: 32', ' QS. Al-Mulk: 1', ' QS. Al-Maidah: 3', 'B', NULL, '', NULL, NULL, NULL, NULL, NULL),
(120, 2, 2, ' Lafadz   فَاسْتَبِقُوا الْخَيْرَاتِ   artinya &hellip;', 1, ' Berlomba-lomba dalam kejelekan', ' Berlomba-lomba dalam kebaikan', ' Menghindari tanggung jawab', ' Menyelesaikan pekerjaan dengan malas', ' Bermegah-megahan', 'B', NULL, '', NULL, NULL, NULL, NULL, NULL),
(121, 2, 3, ' QS. Al-Mulk ayat 2 menjelaskan bahwa &hellip;', 1, ' Mati adalah akhir segalanya', ' Hidup dan mati terjadi secara kebetulan', ' Hidup hanya untuk bersenang-senang', ' Hidup dan mati adalah ujian siapa yang paling baik amalnya', ' Hidup dan mati untuk mengumpulkan harta', 'D', NULL, '', NULL, NULL, NULL, NULL, NULL),
(122, 2, 4, ' Kata kunci QS. Al-Baqarah: 148 adalah &hellip;', 1, ' Takwa', ' Amanah', ' Fastabiqul khairat', '  Zuhud', '  Jihad', 'C', NULL, '', NULL, NULL, NULL, NULL, NULL),
(123, 2, 5, ' Kandungan QS. Al-Maidah ayat 48 adalah &hellip;', 1, '  Allah menciptakan manusia berbangsa-bangsa untuk berlomba dalam kebaikan', ' Larangan membunuh', ' Perintah zakat', ' Perintah puasa', ' Kewajiban berhaji', 'A', NULL, '', NULL, NULL, NULL, NULL, NULL),
(124, 2, 6, ' <i>Ahsanu &lsquo;amala</i> dalam QS. Al-Mulk: 2 bermakna &hellip;', 1, '  Amal yang paling baik dan ikhlas', ' Amal yang paling sedikit', ' Amal yang paling cepat', ' Amal yang hanya mengejar dunia', ' Amal yang tanpa niat', 'A', NULL, '', NULL, NULL, NULL, NULL, NULL),
(125, 2, 7, ' Berlomba dalam kebaikan berarti &hellip;', 1, ' Menjadi yang pertama dalam kejahatan', ' Mengutamakan amal shalih', ' Mengutamakan dunia dari akhirat', ' Malas beribadah', ' Membiarkan orang lain berbuat baik', 'B', NULL, '', NULL, NULL, NULL, NULL, NULL),
(126, 2, 8, ' Hikmah <i>fastabiqul khairat</i> adalah &hellip;', 1, ' Hidup menjadi malas', ' Terjadi perpecahan', ' Hidup produktif dan bermanfaat', ' Sombong', ' Bermegah-megahan', 'C', NULL, '', NULL, NULL, NULL, NULL, NULL),
(127, 2, 9, ' Rasulullah SAW bersabda: <i>&ldquo;Sebaik-baik manusia adalah yang paling bermanfaat bagi manusia lain.&rdquo;</i> Maksudnya &hellip;', 1, ' Hidup untuk diri sendiri', ' Menumpuk harta', ' Berlomba dalam kebaikan', ' Bermalas-malasan', ' Hidup bermegah-megahan', 'C', NULL, '', NULL, NULL, NULL, NULL, NULL),
(128, 2, 10, ' Hadis tentang keutamaan bekerja dengan tangan sendiri bermakna &hellip;', 1, ' Hidup berpangku tangan', ' Mandiri dan bekerja halal', ' Bergantung pada orang kaya', ' Tidak perlu bekerja', ' Bekerja dengan menipu', 'B', NULL, '', NULL, NULL, NULL, NULL, NULL),
(129, 2, 11, ' &ldquo;Allah mencintai seorang mukmin yang bekerja dengan profesional.&rdquo; Hadis ini menekankan nilai &hellip;', 1, ' Ikhlas', ' Amanah', ' Etos kerja', ' Zuhud', ' Sabar', 'C', NULL, '', NULL, NULL, NULL, NULL, NULL),
(130, 2, 12, ' &ldquo;Sebaik-baik pekerjaan adalah pekerjaan dengan tangan sendiri&rdquo; bermakna &hellip;', 1, ' Usaha yang cepat kaya', ' Usaha halal dan mandiri', ' Usaha penuh riba', ' Usaha menipu', ' Usaha tanpa niat', 'B', NULL, '', NULL, NULL, NULL, NULL, NULL),
(131, 2, 13, ' Contoh fastabiqul khairat di sekolah adalah &hellip;', 1, '  Membantu teman memahami pelajaran', '  Menyontek saat ujian', '  Malas belajar', '  Datang terlambat', '  Bermain saat guru mengajar', 'A', NULL, '', NULL, NULL, NULL, NULL, NULL),
(132, 2, 14, ' Membersihkan masjid sekolah sukarela termasuk &hellip;', 1, ' Amal sia-sia', ' Riya&rsquo;', ' Fastabiqul khairat', ' Perilaku tercela', ' Hedonisme', 'C', NULL, '', NULL, NULL, NULL, NULL, NULL),
